export const REGEX_ACCENTS = /[\u0300-\u036f]/g;

export const encodeHtml = (texto: string): string => {
  const p = document.createElement('p');
  p.textContent = texto;
  return p.innerHTML || '';
};

export const decodeHtml = (texto: string): string => {
  const txt = document.createElement('textarea');
  txt.innerHTML = texto;
  return txt.value;
};
