import { generateUUID } from '../../utils/uuid';
import { mostrarToolTipVerificacaoOrtografica } from './toolTipVerificacaoOrtografica';

const Module = Quill.import('core/module');
const Inline = Quill.import('blots/inline');

class Utils {
  static debounce(fn: () => void, delay: number) {
    let timeoutID: number;
    return function (): void {
      clearTimeout(timeoutID);
      timeoutID = window.setTimeout(() => fn(), delay);
    };
  }

  static isWordCharacter = (c: string): boolean =>
    (c ?? '').match(/[\p{L}\d-]/u) !== null;

  static extractWords = (str: string): any[] => {
    const words = [];
    let currentWord = '';
    let currentStart = -1;

    for (let i = 0; i < str.length; i++) {
      if (Utils.isWordCharacter(str[i])) {
        if (currentWord === '') {
          currentStart = i;
        }
        currentWord += str[i];
      } else {
        if (currentWord !== '') {
          words.push({
            offset: currentStart,
            length: currentWord.length,
            word: currentWord,
          });
          currentWord = '';
          currentStart = -1;
        }
      }
    }

    // Adiciona a última palavra se a string terminar com uma palavra
    if (currentWord !== '') {
      words.push({
        offset: currentStart,
        length: currentWord.length,
        word: currentWord,
      });
    }

    return words;
  };
}

export class VerificadorOrtograficoResponse {
  uuid = '';
  word = '';
  offset = 0;
  length = 0;
  ruleId = '';
  issueType = '';
  categoryId = '';
  categoryName = '';
  message = '';
  shortMessage = '';
  suggestions = [];
}

const defaultOptions = {
  debounceTime: 300,
  urlVerificadorOrtografico: '',
  enabled: true,
  callBackVerificadorOrtografico: async function (texto: string): Promise<any> {
    if (!this.urlVerificadorOrtografico || !texto?.trim().length) {
      return [];
    }

    try {
      // O retorno da função deve ser um array de objetos do tipo VerificadorOrtograficoResponse
      const response = await fetch(this.urlVerificadorOrtografico, {
        method: 'POST',
        headers: {
          'Content-Type': 'text/plain',
        },
        body: texto,
      });

      if (!response.ok) {
        console.error(
          'Erro na resposta da verificação ortográfica:',
          response.status,
          response.statusText,
        );
        return [];
      }

      const json = await response.json();
      return json.map((it: any) => ({
        ...it,
        uuid: generateUUID(),
        ignore: false,
      }));
    } catch (error) {
      console.log('Erro ao chamar o verificador ortográfico', error);
      return [];
    }
  },
  callbackRenderErrosOrtograficos: function (): void {},
};

class IgnoreBlot extends Inline {
  static blotName = 'ignore';
  static className = 'ql-ignore';
  static tagName = 'span';

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  static create(_value: any): any {
    const node = super.create();
    return node;
  }

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  static formats(_node: Element): any {
    return true;
  }
}

class MisspellBlot extends Inline {
  static blotName = 'misspell';
  static className = 'ql-misspell';
  static tagName = 'span';

  static create(value: Record<string, string>): any {
    const node = super.create();
    MisspellBlot.updateAttributes(node, value);
    return node;
  }

  static updateAttributes(node: Element, value: Record<string, string>): void {
    if (value) {
      node.setAttribute('data-uuid', value.uuid);
      node.setAttribute('data-rule-id', value.ruleId);
      node.setAttribute('data-issue-type', value.issueType);
      node.setAttribute('data-category-id', value.categoryId);
      node.setAttribute('data-category-name', value.categoryName);
      node.setAttribute('data-message', value.message);
      node.setAttribute('data-short-message', value.shortMessage);
      node.setAttribute('title', value.message);
    }
  }

  static format(node: Element, value: Record<string, string>): void {
    if (value) {
      MisspellBlot.updateAttributes(node, value);
    }
  }

  static formats(node: Element): Record<string, string | null> {
    return {
      uuid: node.getAttribute('data-uuid'),
      ruleId: node.getAttribute('data-rule-id'),
      issueType: node.getAttribute('data-issue-type'),
      categoryId: node.getAttribute('data-category-id'),
      categoryName: node.getAttribute('data-category-name'),
      message: node.getAttribute('data-message'),
      shortMessage: node.getAttribute('data-short-message'),
    };
  }

  //   checkMerge() {
  //     return false;
  //   }

  //   optimize(context) {
  //     super.optimize(context);
  //   }
}

export interface VerificadorOrtograficoOptions {
  debounceTime: number;
  urlVerificadorOrtografico: string;
  enabled: boolean;
  callBackVerificadorOrtografico: (
    // eslint-disable-next-line no-unused-vars
    texto: string,
  ) => Promise<VerificadorOrtograficoResponse[]>;
  callbackRenderErrosOrtograficos: (
    // eslint-disable-next-line no-unused-vars
    erros: VerificadorOrtograficoResponse[],
    errosIgnorados: VerificadorOrtograficoResponse[],
  ) => void;
}

export interface DetalhesEventoErrosOrtograficos {
  codItemReferencia: number;
  erros: VerificadorOrtograficoResponse[];
  errosIgnorados: VerificadorOrtograficoResponse[];
}

export class EditorCustomEventErrosOrtograficos extends CustomEvent<DetalhesEventoErrosOrtograficos> {
  constructor(detalhes: DetalhesEventoErrosOrtograficos) {
    super('editor:erros-ortograficos', {
      detail: detalhes,
      bubbles: true,
    });
  }
}

export class ModuloVerificacaoOrtografica extends Module<VerificadorOrtograficoOptions> {
  static register(): void {
    Quill.register(MisspellBlot, true);
    Quill.register(IgnoreBlot, true);
  }

  erros: VerificadorOrtograficoResponse[] = [];

  termosIgnorados: string[] = [];
  errosIgnorados: VerificadorOrtograficoResponse[] = [];

  constructor(quill: any, options: Partial<VerificadorOrtograficoOptions>) {
    super(quill, options);
    if (!options) return;

    this.quill = quill;
    this.options = { ...defaultOptions, ...options };

    if (this.options.debounceTime) {
      this.quill.on(
        'text-change',
        Utils.debounce(
          this.checkSpelling.bind(this),
          this.options.debounceTime,
        ),
      );
    } else {
      this.quill.on('text-change', this.checkSpelling.bind(this));
    }

    this.quill.root.setAttribute('spellcheck', 'false');

    this.quill.root.addEventListener('click', this.tratarClick.bind(this));
    this.quill.root.addEventListener(
      'verificacao-ortografica:corrigir',
      this.corrigirErroOrtografico.bind(this),
    );
    this.quill.root.addEventListener(
      'verificacao-ortografica:ignorar',
      this.ignorarErroOrtografico.bind(this),
    );
    this.quill.root.addEventListener(
      'verificacao-ortografica:ignorar-todos',
      this.ignorarTodos.bind(this),
    );
  }

  tratarClick(event: any): void {
    const elMisspell = this.getErroOrtograficoMaisProximo(event.target);
    if (!elMisspell) return;
    const uuid = elMisspell.getAttribute('data-uuid');
    const erro = this.erros.find(
      (err: VerificadorOrtograficoResponse) => err.uuid === uuid,
    );
    erro && mostrarToolTipVerificacaoOrtografica(elMisspell, erro);
  }

  corrigirErroOrtografico(event: any): void {
    const { erro, sugestaoSelecionada } = event.detail;
    const el = this.quill.root.querySelector(
      `.ql-misspell[data-uuid="${erro.uuid}"]`,
    );
    if (el) {
      el.innerText = sugestaoSelecionada;
    }
  }

  ignorarErroOrtografico(event: any): void {
    this.processing = true;
    const { erro } = event.detail;
    const el = this.quill.root.querySelector(
      `.ql-misspell[data-uuid="${erro.uuid}"]`,
    );
    if (!el) return;
    this.aplicarFormatoIgnore(el);

    this.errosIgnorados = this.findErrosOrtograficosIgnoradosFromBlots();
    // setTimeout(() => {
    // }, 0);
    this.processing = false;
  }

  ignorarTodos(event: any): void {
    this.processing = true;
    const { erro } = event.detail || {};
    if (!erro?.word) return;

    const termoLower = erro.word.toLowerCase();

    const nodes = Array.from(
      this.quill.root.querySelectorAll('.ql-misspell'),
    ) as HTMLElement[];

    nodes.forEach(domNode => {
      const texto = domNode.innerText || '';
      if (texto.toLowerCase() === termoLower) {
        this.aplicarFormatoIgnore(domNode);
      }
    });

    this.termosIgnorados.push(termoLower);
    this.errosIgnorados = this.findErrosOrtograficosIgnoradosFromBlots();
    // setTimeout(() => {
    // }, 0);
    this.processing = false;
  }

  private aplicarFormatoIgnore(domNode: HTMLElement): void {
    const blot = Quill.find(domNode);
    const offset = blot.offset(this.quill.scroll);
    const length = blot.length();

    try {
      this.quill.formatText(offset, length, { misspell: false }, 'user');
      this.quill.formatText(offset, length, { ignore: true }, 'user');
    } catch {
      // ---
    }
  }

  findErrosOrtograficosIgnoradosFromBlots(): VerificadorOrtograficoResponse[] {
    return Array.from(this.quill.root.querySelectorAll('span.ql-ignore')).map(
      (domNode: any) => {
        const blot = Quill.find(domNode);
        return {
          length: blot.length(),
          offset: blot.offset(this.quill.scroll),
          word: domNode.innerText,
        } as VerificadorOrtograficoResponse;
      },
    );
  }

  getErroOrtograficoMaisProximo(elemento: any): any {
    return elemento?.closest(MisspellBlot.tagName);
  }

  private sincronizarListaDeErrosIgnorados(): void {
    // É preciso remover da lista de errosIgnorados (da classe) os erros que não aparecem na lista "errosIgnoradosFromBlots"
    // Isso porque pode existir blot ignorado que não está na lista (ocorre quando o usuário edita uma área com texto ignorado)
    const errosIgnoradosFromBlots =
      this.findErrosOrtograficosIgnoradosFromBlots();
    this.errosIgnorados = this.errosIgnorados.filter(erroIgnorado =>
      errosIgnoradosFromBlots.some(
        erroBlot =>
          erroBlot.word === erroIgnorado.word &&
          erroBlot.offset === erroIgnorado.offset &&
          erroBlot.length === erroIgnorado.length,
      ),
    );
  }

  async checkSpelling(): Promise<void> {
    if (!this.options.enabled || this.processing) {
      return;
    }

    const text = this.quill.getText();
    const range = this.quill.getSelection();
    this.sincronizarListaDeErrosIgnorados();

    if (this.options.callBackVerificadorOrtografico) {
      this.erros = await this.options.callBackVerificadorOrtografico(text);
    }

    // Separa erros que ainda não estejam formatados como ignorados, mas o termo está na lista "termosIgnorados"
    const novosIgnore = this.erros.filter(
      e =>
        !this.isErroInErrosIgnorados(e) &&
        this.isTermoInTermosIgnorados(e.word),
    );
    this.errosIgnorados.push(...novosIgnore);
    this.errosIgnorados = this.errosIgnorados.sort(
      (e1, e2) => e1.offset - e2.offset,
    );

    this.erros = this.erros.filter(
      e =>
        !this.isErroInErrosIgnorados(e) &&
        !this.isTermoInTermosIgnorados(e.word),
    );

    this.formatarErrosOrtograficos(text, this.erros);
    this.formatarErrosIgnorados(text, this.errosIgnorados);

    if (this.options.callbackRenderErrosOrtograficos) {
      this.options.callbackRenderErrosOrtograficos(
        this.erros,
        this.errosIgnorados,
      );
    }

    // Restaura a seleção do usuário após a verificação ortográfica
    if (range) {
      this.quill.setSelection(range.index, range.length, 'silent');
    }
  }

  isErroInErrosIgnorados(
    erro: VerificadorOrtograficoResponse,
    errosIgnorados: VerificadorOrtograficoResponse[] = this.errosIgnorados,
  ): boolean {
    return errosIgnorados.some(
      ei =>
        ei.word === erro.word &&
        ei.offset === erro.offset &&
        ei.length === erro.length,
    );
  }

  isTermoInTermosIgnorados(termo: string): boolean {
    const termoLower = termo.toLowerCase();
    return this.termosIgnorados.includes(termoLower);
  }

  formatarErrosOrtograficos(
    text: string,
    erros: VerificadorOrtograficoResponse[],
  ): void {
    this.formatar(text, erros, 'misspell', 'ignore');
  }

  formatarErrosIgnorados(
    text: string,
    erros: VerificadorOrtograficoResponse[],
  ): void {
    this.formatar(text, erros, 'ignore', 'misspell');
  }

  private limparFormatacoesDeErros(text = '', formato: string): void {
    this.quill.focus();

    try {
      this.quill.formatText(0, text.length - 1, { [formato]: false }, 'silent');
    } catch {
      // --
    }

    try {
      this.quill.formatText(0, text.length, { [formato]: false }, 'silent');
    } catch {
      // --
    }
  }

  private formatar(
    text: string,
    erros: VerificadorOrtograficoResponse[],
    formatName: string,
    reverseFormatName: string,
  ): void {
    this.limparFormatacoesDeErros(text, formatName);

    erros.forEach(erro => {
      try {
        this.quill.formatText(
          erro.offset,
          erro.length,
          { [reverseFormatName]: false },
          'silent',
        );
        this.quill.formatText(
          erro.offset,
          erro.length,
          formatName,
          erro,
          'silent',
        );
      } catch (error) {
        // --
      }
    });
  }
}
